-- ==================== Java 后端岗（position_id=1）====================

INSERT INTO knowledge_chunk (position_id, title, content, keywords, skill_tags, source_type, status) VALUES
(1, '面向对象三大特性的回答要点',
 '回答封装、继承、多态时要能说清三者解决什么问题，而不是背定义。封装是把数据和操作数据的方法绑定在一起，隐藏内部实现细节，只暴露必要接口，比如把字段私有化再提供访问器，好处是降低耦合、便于维护不变量。继承表达的是一种「is-a」关系，子类复用并扩展父类行为，但滥用继承会造成层次臃肿，面试时要主动提到「组合优于继承」的取舍。多态是同一接口在不同实现上有不同行为，运行期基于实际类型分派虚方法，它是开闭原则的基础：新增一种实现不需要修改调用方代码。结合项目举例时，建议挑一个真实的接口多态场景，比如支付渠道抽象出一个接口，微信、支付宝各自实现，业务层依赖抽象而不是具体实现，再配合 Spring 的依赖注入，新增渠道只需加一个实现类。这样既展示了概念理解，也展示了工程落地能力。常见失分点是只背三大特性的名词而给不出使用场景，或把重载说成多态的运行期体现——重载是编译期静态分派，重写才是运行期多态。',
 '面向对象,封装,继承,多态,重写,重载,组合优于继承,开闭原则,依赖注入,接口抽象,里氏替换,设计原则',
 'java_basics', 'MANUAL', 'ENABLED'),

(1, 'HashMap 底层实现的高分回答框架',
 '讲 HashMap 建议按「整体结构、读写流程、扩容机制、线程安全」四段展开。JDK 8 中结构是数组加链表加红黑树：元素按 hash 定位到桶，冲突时形成链表，链表长度达到 8 且数组容量达到 64 时树化，退化为 6 时退回链表。hash 计算把高 16 位异或到低 16 位，让高位信息参与取模，减少碰撞。put 流程包括计算桶位、处理已存在的 key（equals 比较，相同则覆盖）、否则尾插新节点。扩容阈值是容量的 0.75，超过即 resize 为两倍并重新分布节点，JDK 8 优化为「高低位拆分」，节点要么留在原索引要么移动到原索引加旧容量处，不需要重算 hash。线程安全方面要明确 HashMap 非线程安全，并发扩容在 JDK 7 头插法下会成环死循环，JDK 8 改尾插解决成环但仍会丢数据，并发场景用 ConcurrentHashMap。它按 key 弱等价排序、get 复杂度对数级。能把树化阈值为什么选 8 说成泊松分布下链表长度超 8 概率极低，属于加分项。',
 'HashMap,数组,链表,红黑树,树化,hash扰动,负载因子,0.75,扩容,resize,高低位拆分,头插法,尾插法,ConcurrentHashMap,线程安全',
 'java_basics', 'MANUAL', 'ENABLED'),

(1, 'ArrayList 与 LinkedList 的选型逻辑',
 '两者都实现 List 接口，差异在底层数据结构导致的性能特征。ArrayList 底层是对象数组，支持按下标随机访问，get 是常数时间；扩容在元素超过容量时发生，新容量为旧容量的 1.5 倍，扩容伴随数组复制，所以预估容量、构造时指定初始大小能显著减少复制。中间位置插入删除需要移动后续元素，是线性时间。LinkedList 底层是双向链表，随机访问要从头或尾遍历，get 平均是线性时间；头尾插删是常数时间，这也是它适合队列、双端队列场景的原因。面试常见的误区是把「插入删除快」说成 LinkedList 的普遍优势——实际中间位置插入要先线性找到位置，整体还是线性时间，加上每个节点额外两个引用的内存开销和缓存不友好，业务代码里绝大多数场景 ArrayList 更优。回答时给出明确选型建议并说明依据：默认用 ArrayList，只有明确的队列语义或头尾高频增删才考虑 LinkedList 或 ArrayDeque。能对比内存布局与 CPU 缓存命中对性能的影响是加分项。',
 'ArrayList,LinkedList,数组,双向链表,随机访问,扩容,1.5倍,时间复杂度,ArrayDeque,队列,缓存友好,内存开销,选型',
 'java_basics', 'MANUAL', 'ENABLED'),

(1, '线程池核心参数与任务执行流程',
 'ThreadPoolExecutor 七个核心参数要能一一说明：corePoolSize 核心线程数、maximumPoolSize 最大线程数、keepAliveTime 非核心线程空闲存活时间、unit 时间单位、workQueue 任务队列、threadFactory 线程工厂、handler 拒绝策略。提交流程是回答的关键：当前线程数小于核心线程数时直接建核心线程执行；达到核心数后新任务进队列；队列满后继续创建非核心线程直到最大线程数；线程数达上限且队列满则触发拒绝策略。四种内置拒绝策略是 AbortPolicy 抛异常、CallerRunsPolicy 由提交线程自己执行、DiscardPolicy 静默丢弃、DiscardOldestPolicy 丢最老任务。要能解释为什么「先入队再扩线程」：队列通常容量较大，线程是更昂贵的资源，这个顺序让系统优先用少量线程处理可缓冲的任务。参数配置要结合任务类型：CPU 密集型接近核数加一，IO 密集型可按核数乘以（一加 IO 等待占比）估算，并强调应通过压测确定而不是套公式。生产上还建议给线程池命名并监控队列长度与活跃线程数，Executors 工厂方法因为无界队列或 Integer 最大值线程数有 OOM 风险，阿里规约要求手动创建。',
 '线程池,ThreadPoolExecutor,corePoolSize,maximumPoolSize,workQueue,拒绝策略,AbortPolicy,CallerRunsPolicy,keepAliveTime,任务队列,CPU密集,IO密集,压测,Executors,OOM',
 'concurrency_jvm', 'MANUAL', 'ENABLED'),

(1, 'synchronized 与 ReentrantLock 的对比',
 '两者都是可重入互斥锁，选型对比建议分五个维度。实现层面：synchronized 是 JVM 内置关键字，基于对象头 Mark Word 与 monitor，JDK 6 引入偏向锁、轻量级锁、自旋锁做了大量优化，锁升级路径是无锁到偏向锁到轻量级锁到重量级锁；ReentrantLock 是 juc 包基于 AQS 的实现。功能层面：ReentrantLock 支持尝试获取 tryLock 带超时、可中断获取 lockInterruptibly、公平锁构造参数、以及多个条件变量 Condition 精确唤醒，synchronized 只有 wait notify notifyAll 一个等待集。使用层面：synchronized 自动释放锁，异常也不会忘记解锁；ReentrantLock 必须在 finally 里 unlock，否则死锁风险。性能层面：JDK 6 之后两者差距已经很小，无特殊功能需求默认 synchronized。底层机制层面：能说出 AQS 的 state 变量与 CLH 队列、独占模式获取释放的模板方法，是明显加分项。回答时最好给一个实际选择案例，比如需要「尝试拿锁拿不到就降级返回」的防重复提交场景用 tryLock，普通互斥直接 synchronized。',
 'synchronized,ReentrantLock,monitor,Mark Word,锁升级,偏向锁,轻量级锁,自旋,AQS,CLH队列,tryLock,lockInterruptibly,公平锁,Condition,可重入',
 'concurrency_jvm', 'MANUAL', 'ENABLED'),

(1, 'JVM 内存区域划分与 OOM 定位',
 '运行时数据区分为线程私有的程序计数器、虚拟机栈、本地方法栈，与线程共享的堆、方法区（JDK 8 后由元空间实现，字符串常量池在堆）。程序计数器唯一不会 OOM；栈深度超限抛 StackOverflowError，栈容量也可在无法申请时 OOM；堆 OOM 最常见，典型报错是 Java heap space；元空间受本地内存限制，加载类过多（如反射代理滥用）会 Metaspace OOM；直接内存 OOM 常见于 NIO 的 DirectByteBuffer。回答时要能对每个区域说明存放什么：栈帧里有局部变量表、操作数栈、动态链接、返回地址；对象实例在堆，类元信息在元空间。OOM 排查思路要体现工程能力：先用 jmap 或启动参数 dump 堆快照，再用 MAT 或 JProfiler 分析支配树找最大对象，结合代码定位泄漏来源；常见泄漏有静态集合持有对象、资源未关闭、ThreadLocal 在线程池里不 remove、监听器未注销。线上应急三步是：保留现场（dump 与 GC 日志）、临时扩容或重启止血、再离线分析根治。能区分内存泄漏与内存溢出概念，并提到 -Xms -Xmx -XX:+HeapDumpOnOutOfMemoryError 参数是加分项。',
 'JVM,运行时数据区,程序计数器,虚拟机栈,本地方法栈,堆,方法区,元空间,OOM,StackOverflowError,DirectByteBuffer,jmap,MAT,堆快照,内存泄漏,ThreadLocal,HeapDumpOnOutOfMemoryError',
 'concurrency_jvm', 'MANUAL', 'ENABLED'),

(1, 'Spring IOC 与依赖注入的回答要点',
 'IOC 控制反转是一种设计思想：对象的创建与依赖关系的维护从程序代码转移到容器，开发者只声明需要什么，容器负责装配。依赖注入 DI 是它的主要实现方式，通过构造器、setter 或字段把依赖送进来。它解决的问题是解耦与可测试性：调用方依赖抽象接口，实现类由容器按配置装配，替换实现不需要改调用代码；单元测试可以注入 Mock 对象。回答时要能说清反射与工厂的角色：容器启动时扫描注解或读取配置，用反射实例化 Bean，解析依赖后递归装配，三级缓存解决属性注入的循环依赖——singletonObjects 存成品、earlySingletonObjects 存早期暴露对象、singletonFactories 存工厂，只能解决单例 setter 注入的循环，构造器循环依赖直接报错。常见误区是把 IOC 等同于 DI 而不说区别，或者只会 @Autowired 注解而讲不出容器做了什么。加分点：对比服务定位器；说明 Spring Boot 的自动装配如何在此基础上按条件注解装配第三方 Bean。',
 'IOC,控制反转,DI,依赖注入,容器,反射,三级缓存,循环依赖,singletonObjects,BeanFactory,解耦,可测试性,Autowired,自动装配,条件注解',
 'spring', 'MANUAL', 'ENABLED'),

(1, 'Spring Bean 生命周期与作用域',
 'Bean 生命周期可以按「实例化、属性填充、初始化、使用、销毁」五阶段展开。实例化阶段容器通过反射调用构造器或工厂方法创建原始对象；属性填充阶段完成依赖注入；初始化前后有 BeanPostProcessor 的 postProcessBeforeInitialization 与 postProcessAfterInitialization 两个扩展点，AOP 代理通常在后置处理中生成；声明的初始化回调按注解、接口、配置方法的顺序执行；容器关闭时注册的销毁回调被调用。把 Aware 接口系列（BeanNameAware、BeanFactoryAware、ApplicationContextAware）放进对应阶段能体现深度。常见作用域：singleton 默认，容器内一个实例；prototype 每次获取新建，容器不再管理其销毁；web 环境还有 request、session、application。作用域的经典坑是 singleton Bean 注入 prototype Bean 时后者被固定，解决方案是用 ObjectProvider 或 @Lookup 按需获取。常见失分点是背不出扩展点顺序，或不知道 AOP 代理发生在哪一步——回答出 AnnotationAwareAspectJAutoProxyCreator 在初始化后生成代理，是明显的加分信号。',
 'Bean生命周期,实例化,属性填充,BeanPostProcessor,初始化回调,销毁回调,Aware接口,AOP代理,proxy,singleton,prototype,request,session,ObjectProvider,Lookup,作用域',
 'spring', 'MANUAL', 'ENABLED'),

(1, 'Spring 事务传播行为与失效场景',
 '七种传播行为重点掌握三种：REQUIRED 默认，当前有事务就加入，没有就新建；REQUIRES_NEW 挂起当前事务并开新事务，内层提交回滚独立于外层，典型用途是记录操作日志，业务回滚了日志也要落库；NESTED 嵌套事务，基于保存点，内层回滚只回到保存点，外层可继续提交，它与 REQUIRES_NEW 的区别是内层依赖外层，外层回滚内层必然回滚。回答要配代码场景，比如下单方法调用扣库存与记流水，记流水用 REQUIRES_NEW 保证异常时仍留痕。事务失效的八股同样重要：自调用不走代理导致注解失效；方法非 public；异常被 catch 吞掉；默认只回滚 RuntimeException 与 Error，受检异常需 rollbackFor 指定；多线程里子线程不在同一事务；数据库引擎不支持事务；传播行为设置不当；Bean 没被 Spring 管理。能从「事务由 AOP 代理实现」这个根因出发解释自调用失效，比死记场景更有说服力。',
 '事务,传播行为,REQUIRED,REQUIRES_NEW,NESTED,保存点,rollbackFor,自调用,AOP代理,失效,受检异常,RuntimeException,挂起,嵌套事务,日志留痕',
 'spring', 'MANUAL', 'ENABLED'),

(1, 'MySQL 为什么用 B+ 树做索引',
 '对比要从磁盘 IO 次数与范围查询两个角度讲。哈希索引等值查询是常数时间，但不支持范围查询与排序，无法用于最左前缀匹配。二叉搜索树与红黑树是二叉结构，数据量大时树高很高，每个节点一次 IO，查询代价等于树高。B 树每个节点存键与数据、多路分叉降低了树高，但每个节点都带整行数据导致单页容纳的键变少，树反而变高，且范围查询要中序回溯。B+ 树非叶子节点只存键不存数据，同样 16KB 的页能放更多键，三层即可索引约两千万行；数据全部在叶子层且叶子间有双向链表，范围查询与排序沿链表顺序扫描即可。聚簇索引与二级索引的区别也是高频追问：主键索引叶子存整行，二级索引叶子存主键值，走二级索引查非索引列需要回表，覆盖索引避免回表是优化重点。建议用一个量化例子说明树高：主键 bigint 8 字节加页指针 6 字节，一页约可放 1170 个索引项，三层结构容量约两千万，一次主键查询最多三次页 IO。这样回答既有原理又有数字，说服力强。',
 'B+树,B树,红黑树,哈希索引,聚簇索引,二级索引,回表,覆盖索引,最左前缀,页,16KB,树高,范围查询,双向链表,磁盘IO',
 'mysql', 'MANUAL', 'ENABLED'),

(1, '索引失效场景与慢 SQL 排查方法',
 '常见索引失效场景要能成组说出：对索引列做函数或运算、隐式类型转换（字符串列传数字）、前导模糊匹配 like 百分号开头、联合索引不满足最左前缀、or 两侧存在无索引列、not in 与不等于在特定选择性下放弃索引、优化器评估回表成本过高选择全表扫描。排查慢 SQL 的标准流程：先开慢查询日志定位语句，用 explain 看执行计划，重点关注 type 访问类型（range 以上较好）、key 实际使用的索引、rows 估计扫描行数、extra 里是否出现 Using filesort 与 Using temporary；再用 show profile 或性能模式分析各阶段耗时。优化手段按优先级：改写 SQL 让其命中索引、加或调整联合索引顺序、覆盖索引消除回表、深分页改游标或延迟关联、必要时加缓存或读写分离分摊负载。回答场景题「接口从 50 毫秒变 3 秒」时，按「看监控定位慢在哪一段、数据库看慢日志与执行计划、对比变更与数据量增长、验证优化效果」的顺序展开，体现的是排查方法论而不是背题。',
 '慢SQL,慢查询日志,explain,type,rows,Using filesort,Using temporary,索引失效,隐式转换,最左前缀,前导模糊,回表,覆盖索引,深分页,延迟关联,执行计划',
 'mysql', 'MANUAL', 'ENABLED'),

(1, 'MySQL 事务隔离级别与 MVCC',
 '四个隔离级别按严重程度递减：读未提交存在脏读；读已提交解决脏读但存在不可重复读；可重复读是 InnoDB 默认级别，解决不可重复读，并在间隙锁加持下基本防止幻读；串行化全部加锁。MVCC 是读已提交与可重复读的实现基础：每行隐藏字段 trx_id 记录最后修改事务、roll_pointer 指向 undo 日志版本链；读数据时按视图规则从版本链上找对自己可见的版本。两个级别的差异只在快照建立时机——读已提交每条语句新建视图，可重复读在事务首次查询时建视图并沿用，这就是前者能看见别人已提交修改而后者不能的原因。写操作走当前读，需要读最新版本，所以 update 会加锁。能讲清「快照读与当前读的区别」以及 RR 级别下 update 影响行数与预期不一致的案例，说明真正理解了版本链。延伸到长事务的风险：长事务持有旧视图导致 undo 链无法清理、回滚段膨胀，监控里要关注事务持续时间。',
 '事务隔离,读未提交,脏读,不可重复读,可重复读,幻读,MVCC,trx_id,roll_pointer,undo日志,版本链,ReadView,快照读,当前读,间隙锁,长事务',
 'mysql', 'MANUAL', 'ENABLED'),

(1, '缓存穿透、击穿、雪崩的区别与对策',
 '三者要能一句话区分：穿透是查「不存在的数据」，缓存与数据库都没有，请求全部打到数据库；击穿是「某个热点 key」过期瞬间高并发直达数据库；雪崩是「大面积 key」同时失效或缓存服务整体不可用。对策各自对应：穿透用空值缓存（短 TTL 防止被反复穿透）、布隆过滤器前置拦截、接口层参数校验；击穿用互斥锁保证只有一个线程回源重建、逻辑过期（物理不过期，值里带过期时间，异步刷新）、热点 key 永不过期加后台更新；雪崩用 TTL 加随机抖动错开过期、缓存集群高可用（哨兵或集群模式）、多级缓存、限流熔断兜底。回答建议按「现象、根因、对策、代价」展开，比如互斥锁防击穿要说明它牺牲了吞吐、可能造成线程堆积，需要配超时；逻辑过期要说明存在短暂脏数据窗口。结合秒杀场景举例：库存热点 key 用逻辑过期加原子扣减，未命中的冷数据用布隆过滤，整体 TTL 加抖动。能对比出「同一把锁粒度太粗会退化成串行」的取舍是加分项。',
 '缓存穿透,缓存击穿,缓存雪崩,空值缓存,布隆过滤器,互斥锁,逻辑过期,热点key,TTL,随机抖动,多级缓存,限流,熔断,哨兵,重建缓存',
 'redis_mq', 'MANUAL', 'ENABLED'),

(1, 'Redis 持久化 RDB 与 AOF 的取舍',
 'RDB 是某一时刻全量内存快照，二进制紧凑、恢复快，但两次快照之间的数据会丢，fork 子进程执行 bgsave 时写时复制保证主进程继续服务，内存占用大时 fork 可能有秒级停顿。AOF 追加写命令日志，丢数据窗口取决于刷盘策略：always 每条刷最安全最慢、everysec 每秒刷是推荐折中、no 交给操作系统最快最不安全；文件大时 AOF 重写按当前数据状态生成最小命令集。4.0 后混合持久化在 AOF 重写时先写全量 RDB 再追加增量命令，兼顾恢复速度与数据安全，生产推荐开启。选型建议：纯缓存场景可关持久化或只开 RDB；不能丢数据（如计数、去重）开 everysec AOF 加混合持久化。追问点：主从复制与持久化的关系—— replicas 不需要持久化时也要防范主从同时重启丢数据；fork 停顿在大内存实例的监控与规避（关 THP、控制单实例内存、用高版本 LFU）。能把「恢复优先级 AOF 高于 RDB、两者共存时以 AOF 为准」说准，说明真正用过。',
 'RDB,AOF,bgsave,fork,写时复制,appendfsync,everysec,AOF重写,混合持久化,全量快照,命令日志,恢复速度,数据安全,主从复制',
 'redis_mq', 'MANUAL', 'ENABLED'),

(1, '消息积压百万条的处理思路',
 '先定位再治理。定位：看消费滞后量与增长速率，区分是消费能力不足、消费失败反复重试、还是上游流量突增；看消费端线程栈与慢日志，常见瓶颈是单条消息处理里同步调数据库或外部接口、串行消费、大消息。应急：如果消息允许丢弃，按业务降级（如日志类直接丢弃或抽样）；扩容消费者实例数，注意分区或队列数要不小于消费者数，不够先扩队列；临时新起一组消费者把消息快速搬到新队列再分片并行处理。治理：批量消费减少网络往返；异步化与本地批处理；把非核心链路改为异步旁路；对可重试失败消息配死信队列并监控告警；给消费端加限流保护下游。回答时强调顺序性与重复消费两个约束：分片搬运要按 key 哈希保证同 key 顺序；消费逻辑要幂等（唯一键、状态机、去重表）。预防层面，容量评估与压测、按峰值两到三倍冗余、监控消费延迟指标，这些体现体系化思维。',
 '消息积压,消费滞后,扩容,批量消费,分片,新队列,死信队列,幂等,顺序性,重复消费,限流,消费能力,吞吐,监控告警,容量评估',
 'redis_mq', 'MANUAL', 'ENABLED'),

(1, '秒杀场景防超卖的完整方案',
 '防超卖的核心是把「查库存、判断、扣减」三步变成原子操作。数据库层方案：update 库存 set num = num - 1 where id = ? and num > 0，利用行锁与条件更新保证不超卖，影响行数为零即售罄，配合乐观重试；热点行锁竞争激烈时会成为瓶颈。缓存层方案：Redis 预扣库存，用 Lua 脚本原子执行判断加扣减，成功后再异步落库（消息队列削峰），数据库最终一致；Redis 单 key 热点可用分片库存（拆成多个子 key 轮询扣）缓解。完整链路分层表述：前端按钮防抖与答题验证码削峰；网关层限流（令牌桶）与黑名单；应用层库存预检、一人一单（唯一索引或 Redis set 判重）；缓存原子预扣；消息队列异步下单；数据库乐观扣减兜底加对账。要主动说明一致性与补偿：预扣成功但下单失败要有回补（延迟消息回滚库存），定时对账修正漂移。追问「为什么不用分布式锁」时，回答粒度粗、吞吐低，条件更新或 Lua 原子操作更轻量。这种分层加兜底的回答结构是场景题的满分模板。',
 '秒杀,超卖,原子扣减,条件更新,行锁,乐观锁,Lua脚本,Redis预扣,分片库存,消息队列,削峰,限流,一人一单,唯一索引,异步下单,对账,回补',
 'project_design', 'MANUAL', 'ENABLED'),

(1, '线上接口变慢的系统化排查思路',
 '先界定范围再逐层下钻。第一步看监控确定是「单接口慢」还是「整体慢」：单接口慢多半是该接口依赖或数据量问题；整体慢看应用与资源水位。应用层：检查 GC 日志与线程池饱和度，频繁 Full GC 或线程池队列堆积都会拖慢；看是否有慢查询外部调用没有超时，级联等待拖垮线程。数据库层：慢查询日志定位 SQL，explain 分析执行计划，关注是否新查询没走索引、数据量增长导致执行计划变化、锁等待（查信息架构 innodb_trx 与锁等待表）。缓存层：缓存命中率是否下跌、是否有大面积失效、Redis 是否慢查询（大 key、热 key、持久化抖动）。基础设施：网络抖动、磁盘 IO、容器 CPU 限流。变更回溯是最有效的线索：最近发布、配置变更、数据导入、营销流量。回答模板：50 毫秒变 3 秒的例子里，先看链路追踪定位耗时分布，若 90% 时间在数据库，则查执行计划对比历史，常见根因是统计信息过期导致索引选择变化，analyze table 或强制索引即可止血，再补监控与索引评审根治。体现「先定位、再止血、后根治」的顺序感是关键。',
 '性能排查,接口变慢,慢查询,执行计划,GC日志,线程池,缓存命中率,链路追踪,锁等待,变更回溯,监控,止血,根治,索引选择,统计信息',
 'project_design', 'MANUAL', 'ENABLED'),

(1, '用户量增长一百倍后的瓶颈推演',
 '按请求链路逐层推演瓶颈并给方案，体现容量思维。接入层：nginx 单机连接数上限，加负载均衡横向扩容，动静分离。应用层：无状态服务直接加实例，但要检查会话与本地缓存是否阻碍水平扩展；线程池与连接池配置是否够。数据库最先成为瓶颈：连接数打满、慢查询放大、写入增长。路径依次是读写分离分摊读、垂直拆库按业务域、水平分片按用户哈希、热点数据缓存前置。分库分表要提带来的代价：跨片查询与事务、全局 id（雪花或号段）、扩容迁移（双写迁移）。缓存层：Redis 单机内存与吞吐上限，主从加哨兵或集群分片，热 key 与大 key 治理。消息与任务：削峰填谷、异步化。可观测性贯穿始终：容量水位、限流降级预案。回答的加分结构是「先说不会拍脑袋扩容，而是按监控数据找真实瓶颈，再按投入产出排序改造」，同时说明单体到微服务是按业务边界渐进拆分而不是一步到位。',
 '容量,扩展性,读写分离,垂直拆分,水平分片,分库分表,全局ID,雪花算法,双写迁移,负载均衡,无状态,连接池,缓存前置,限流降级,微服务拆分',
 'project_design', 'MANUAL', 'ENABLED'),

(1, '结构化表达：总分总与 STAR 法',
 '技术面试的表达质量直接影响评分。回答概念题用总分总：先一句话给结论，再分两到四点展开，每点有论据或例子，最后一句话收束。例如被问索引为什么用 B+ 树，先说「核心是为了减少磁盘 IO 并高效支持范围查询」，再从对比哈希、B 树、树高量化三点展开，最后收「所以 OLTP 场景 B+ 树是综合最优解」。回答项目与经历题用 STAR：情境 Situation 交代背景与约束，任务 Task 说明你的职责边界，行动 Action 讲关键技术决策与取舍（这是重点，占六成篇幅），结果 Result 用数据量化收益。常见失分：铺垫过长三十秒没进正题；只讲做了什么不讲为什么这么选；没有量化结果；被打断后逻辑断裂。练习方法是录音复盘：每题限时两分钟，听回放删掉「嗯、然后、就是」等口头语。面试前准备三到五个能覆盖多类追问的项目故事，比临场组织更稳。',
 '结构化表达,总分总,STAR法则,量化结果,技术取舍,口头语,录音复盘,限时练习,逻辑递进,一句话结论,论据,收束,沟通技巧',
 'communication', 'MANUAL', 'ENABLED'),

(1, '技术分歧的沟通方法',
 '被问「与团队成员意见不一致怎么办」，考察的是协作成熟度。回答框架：先对齐目标再讨论方案——分歧大多源于双方优化目标不同，一方关注开发效率一方关注长期维护成本，先确认共同目标（按时上线且不留下大坑），方案分歧就容易收敛。其次用事实与数据代替立场争论：各自列出方案的优缺点矩阵，评估实现成本、风险、扩展性，必要时做小规模原型或压测验证关键假设，让数据说话。再区分决策权：架构级分歧升级到技术负责人裁决，团队要有决策机制而不是无限讨论。分歧解决后要落实：会议纪要写清结论、依据与待办，避免翻旧账。举例模板：联调接口时与前端同事对错误码格式有分歧，我提议按团队既有规范统一响应结构并给出迁移成本评估，半天内达成一致。要避免的雷区：说「我都听别人的」显得没主见；说「我坚持我的直到对方同意」显得难合作；举的例子里贬低对方。',
 '技术分歧,对齐目标,优缺点矩阵,数据说话,原型验证,决策机制,会议纪要,协作,沟通,升级裁决,成本评估,团队规范,换位思考',
 'communication', 'MANUAL', 'ENABLED'),

(1, '压力应对与学习方法的高分回答',
 '讲压力下的经历要突出「方法论」而不是情绪。结构建议：先一句话定义当时的压力（工期紧、需求变更、线上故障），再讲如何拆解——区分必须做与可以砍的、排优先级、主动同步风险争取资源或调整范围，最后给结果与复盘。例如赶工期时用「先保核心链路、次优先级功能延后」的策略，每天站会同步进度与阻塞，最终按时交付核心功能，复盘沉淀了任务估时模板。避免抱怨队友或公司；重点是你主动做了什么。学习方法题的回答要体现体系化：信息源分级（官方文档优先于博客）、以输出倒逼输入（写笔记、做小项目、给同学讲）、用间隔重复巩固；最近在学什么要真实且能与岗位关联，比如在学这门课对应的技术栈时顺带读了某框架的部分源码，能说出一个具体细节（如三级缓存或 B+ 树页分裂）远比罗列一堆名词可信。两个题共同的原则：用具体事例支撑通用方法论。',
 '压力应对,优先级,主动同步,风险管理,复盘,估时,学习方法,官方文档,输出倒逼输入,间隔重复,小项目,源码阅读,具体细节,体系化',
 'communication', 'MANUAL', 'ENABLED');

-- ==================== Web 前端岗（position_id=2）====================

INSERT INTO knowledge_chunk (position_id, title, content, keywords, skill_tags, source_type, status) VALUES
(2, '盒模型与 box-sizing 的回答要点',
 '盒模型从内到外是 content、padding、border、margin 四层。标准盒模型（box-sizing: content-box）里 width 只含内容区；IE 盒模型（border-box）里 width 包含内容、内边距与边框。转换通过 box-sizing 属性设置，工程里普遍在全局样式里设 border-box，原因是这样设宽度就是元素占位的实际宽度，加 padding 或 border 不会撑破布局，栅格系统计算更直观。回答时可以延伸到层叠上下文与盒模型相关的调试技巧：margin 折叠现象只发生在垂直方向的相邻块级元素间，BFC（块级格式化上下文）可以包含内部 margin，触发方式如 overflow 非 visible、display flow-root（现代推荐，无副作用）。再延伸到 flex 布局里 min-width auto 导致的收缩异常，用 min-width 0 解决。高分回答的标准：概念准确、说得出两种盒模型的实际影响、能给出一两个实战踩坑例子，而不是只背名词。常见失分是把 margin 折叠说成所有方向都会发生，或把 box-sizing 说成改变渲染引擎。',
 '盒模型,content-box,border-box,box-sizing,padding,border,margin,margin折叠,BFC,flow-root,层叠上下文,flex,min-width,标准盒模型,IE盒模型',
 'html_css_js', 'MANUAL', 'ENABLED'),

(2, '事件循环：宏任务与微任务的执行顺序',
 'JS 单线程下靠事件循环调度异步任务。执行栈跑完当前同步代码后，先清空微任务队列（Promise then、queueMicrotask、MutationObserver），再取一个宏任务（setTimeout、setInterval、IO、UI 渲染）执行，执行完再次清空微任务，如此循环。关键细节：微任务在每个宏任务之间全部执行完；await 会把后续代码放进微任务；Promise 构造函数里的代码是同步执行的，then 回调才是微任务；setTimeout 最小延迟约 4 毫秒且嵌套超五层后被限到 4 毫秒以上，不保证精确时序。经典输出题的解题套路：先标出所有同步代码、再按「谁先注册谁先出队」排队微任务、宏任务按定时器到点顺序。浏览器与 Node 的差异在 Node 11 后已基本对齐（每执行一个宏任务清微任务），timers、poll、check 各阶段可以简单带过。延伸加分：讲清为什么 React 早期用 MessageChannel 而不是 setTimeout 做调度（宏任务粒度差异），以及长任务超过 50 毫秒会阻塞渲染，需要用任务切片让出主线程。',
 '事件循环,Event Loop,宏任务,微任务,Promise,await,queueMicrotask,setTimeout,任务队列,执行栈,Node,长任务,任务切片,MessageChannel,渲染阻塞',
 'html_css_js', 'MANUAL', 'ENABLED'),

(2, '闭包的概念、应用与内存注意事项',
 '闭包是函数与其词法作用域的组合：内层函数引用了外层函数的变量，即使外层已执行结束，被引用的变量仍保存在内存里可被内层访问。形成条件是「函数嵌套加内层引用外层变量加内层被外部持有」。实际应用：模块模式用立即执行函数封装私有变量暴露接口；函数柯里化与偏应用依赖闭包保存参数；防抖节流用闭包维护计时器与上下文；React 早期 Hooks 的实现思想也与函数组件每次渲染形成的闭包快照有关，这解释了 useEffect 依赖数组与闭包捕获旧值的问题。内存注意事项是高频追问：闭包持有大对象且长期存活（如全局事件监听器里的闭包）会造成内存泄漏，解法是及时解绑监听、把大对象置空、用弱引用 WeakMap 存可被回收的关联数据。回答时建议现场写一个计数器或防抖函数并解释哪一处形成了闭包、变量存在哪里，能写对基本就拿到高分。常见失分：说闭包会必然导致内存泄漏（错，只有不再需要却无法回收才是泄漏），或背不出形成条件。',
 '闭包,词法作用域,私有变量,模块模式,柯里化,防抖,节流,内存泄漏,解绑监听,WeakMap,Hooks,闭包捕获,立即执行函数,计数器,垃圾回收',
 'html_css_js', 'MANUAL', 'ENABLED'),

(2, '从输入 URL 到页面渲染的完整链路',
 '按五段展开：网络、解析、样式、布局绘制、加载优化。网络段：浏览器缓存查找（强缓存协商缓存）、DNS 解析（递归查询，本地缓存分层）、TCP 三次握手与 TLS 握手（HTTPS）、HTTP 请求响应。解析段：字节流经分词生成 token，构建 DOM 树；遇到 CSS 构建 CSSOM；遇到 script 默认阻塞解析，defer 延迟到 DOM 完成后按序执行、async 下载完立即执行且不保证顺序。渲染段：DOM 与 CSSOM 合成渲染树，布局计算几何信息得到布局树，绘制填充像素生成图层，合成线程把图层分块后交 GPU 合成上屏；transform 与 opacity 只触发合成不重排，这就是动画优先用 transform 的原因。优化连接点：关键 CSS 内联、脚本 defer、资源预加载 preload 与预连接 preconnect、图片懒加载。回答的深度信号：能区分重排（布局变化）与重绘（外观变化）的触发条件与性能差异，能说清为什么操作 DOM 昂贵（跨进程通信与可能的重排）。这是前端最有代表性的综合题，结构完整比细节堆砌重要。',
 'URL,渲染流程,DNS解析,TCP握手,TLS,DOM树,CSSOM,渲染树,布局,绘制,合成,重排,重绘,transform,defer,async,preload,关键CSS,GPU合成',
 'browser_network', 'MANUAL', 'ENABLED'),

(2, '同源策略与 CORS 的工作机制',
 '同源策略限制脚本跨源读取响应，协议、域名、端口三者任一不同即跨源。它是浏览器行为，服务器之间通信不受限，所以服务端转发（代理）能绕开。CORS 是标准化的跨源方案：简单请求（GET、POST、HEAD 且安全头部）直接发送，浏览器在响应里检查 Access-Control-Allow-Origin；非简单请求（如带自定义头、Content-Type 为 JSON 的 POST）先发 OPTIONS 预检，服务器返回允许的源、方法、头部与预检缓存时长，通过后才发真实请求。携带 Cookie 时必须同时满足：前端 withCredentials 为真、响应头 Allow-Origin 为具体域名不能是星号、Allow-Credentials 为真。常见排查：预检失败看 OPTIONS 是否被网关或安全策略拦截；允许的头部要逐个列出（如 Authorization、Content-Type）。与其他方案对比：JSONP 只支持 GET 且有注入风险，基本淘汰；图片打点适合无响应体上报；postMessage 用于窗口间通信；开发期用 Vite 代理把跨源变成同源是工程常态。能说清「为什么 token 放 Header 更适合 CORS、Cookie 跨站要配 SameSite」是安全意识的加分点。',
 '同源策略,CORS,跨域,预检请求,OPTIONS,Allow-Origin,withCredentials,Allow-Credentials,代理,JSONP,postMessage,Vite代理,SameSite,安全头部',
 'browser_network', 'MANUAL', 'ENABLED'),

(2, 'HTTP 强缓存与协商缓存',
 '缓存判定顺序：先强缓存，命中直接用本地副本不发请求；未命中走协商缓存，发请求带条件头部由服务器判定，未变更返回 304。强缓存的两个字段：Expires 是绝对时间（HTTP 1.0，受本地时钟影响）；Cache-Control 相对秒数优先级更高，max-age 定义新鲜期，public private 控制中间层缓存，no-store 完全不存，no-cache 是可以存但每次必须协商（高频误解点）。协商缓存两对字段：Last-Modified 与 If-Modified-Since 基于修改时间，秒级精度且内容不变的时间戳更新会误判；ETag 与 If-None-Match 基于内容指纹优先级更高。工程实践：带哈希指纹的静态资源（文件名含 contenthash）设长 max-age 一年，强制缓存；HTML 入口文件设 no-cache 每次协商，保证发版即时生效；接口按业务设短缓存或不缓存。排查工具：Network 面板看 Size 列 from memory cache 与 from disk cache，看响应头与 304。加分点：说清 Service Worker 与 HTTP 缓存的层次关系，以及 Vary 头对按头部区分缓存的作用。',
 '强缓存,协商缓存,Cache-Control,max-age,Expires,no-cache,no-store,ETag,If-None-Match,Last-Modified,304,contenthash,from memory cache,Service Worker,Vary,缓存策略',
 'browser_network', 'MANUAL', 'ENABLED'),

(2, 'Vue3 响应式原理：从 defineProperty 到 Proxy',
 'Vue2 用 Object.defineProperty 劫持属性的 getter setter，缺陷：无法监听属性新增删除（需要 set delete 等补丁 API）、数组索引与 length 变更需要方法重写、初始化时递归整棵对象树开销大。Vue3 改用 Proxy 代理整个对象：拦截 get、set、deleteProperty、has 等十三种操作，新增删除属性天然响应，数组索引直接支持，且惰性代理——嵌套对象只在被访问时才转响应式，初始化成本大幅下降。依赖收集机制：组件渲染时触发响应式数据的 get，当前渲染副作用（effect）被收集进该属性的依赖集合（Map 加 Set 结构）；数据 set 时触发对应副作用重新执行，组件粒度的更新按调度器去重批量刷新，配合 patch 阶段的静态提升与块结构做最小化 DOM 更新。ref 的存在是因为 Proxy 无法代理原始值，ref 用带 value 访问器的类实例封装原始值，模板里自动解包。能讲清「为什么需要 effect 的嵌套栈来维护当前活跃副作用」以及批量更新的微任务调度，是深度信号；能对比 React 不可变数据方案的设计取舍是加分项。',
 '响应式,Proxy,defineProperty,依赖收集,副作用,effect,批量更新,scheduler,patch,ref,自动解包,惰性代理,数组索引,新增属性,静态提升',
 'vue3', 'MANUAL', 'ENABLED'),

(2, 'ref 与 reactive 的选择',
 '两者都是创建响应式数据的 API，机制不同：ref 包装任意值，内部用 RefImpl 类的 get set value 拦截，对象类型的值内部仍会转 reactive 代理；reactive 直接返回目标对象的 Proxy，只支持对象与集合类型。行为差异要注意三点：解构会破坏 reactive 的响应（解构拿到的是普通值），需要 toRefs 或 toRef 保持响应式，而 ref 解构后仍要通过 value 访问；ref 在 script 里要 .value，模板自动解包，reactive 直接用；整体替换 reactive 对象（直接赋新值）会丢失响应引用，ref 没有这个问题。社区与官方风格指南的建议：用 ref 作为主推的声明方式（与组合式函数返回值、类型推导更一致），reactive 适合「一组相关状态的分组」场景。类型层面：ref 泛型推导对联合类型与深层对象更友好；reactive 隐式解包发生在嵌套 reactive 属性里。回答给一个明确立场并说出理由，比「看个人喜好」更好；提到团队规范统一风格是工程意识。追问点：shallowRef 与 triggerRef 的使用场景（大列表性能优化、第三方实例托管）。',
 'ref,reactive,toRefs,toRef,value,模板解包,响应式丢失,整体替换,RefImpl,泛型推导,组合式函数,shallowRef,triggerRef,风格指南,状态分组',
 'vue3', 'MANUAL', 'ENABLED'),

(2, '组件通信方式与状态管理的选型',
 '按关系分层回答通信方式：父子用 props 与 emit（单向数据流，子组件不改 props，用 defineProps defineEmits 类型化声明）；跨层用 provide inject，适合组件库内部与主题注入，注意用 readonly 包裹注入值防止误改；引用模板用 ref 拿实例调方法（defineExpose 暴露）；任意组件间小型场景用事件总线或 tiny-emitter，但难追踪不推荐滥用；全局状态用 Pinia。为什么复杂状态用集中式状态管理：跨组件共享状态的变更来源可追踪（devtools 时间旅行）、逻辑按领域拆分成 store 而不是散在各组件、服务端状态与本地状态分离、避免 props 钻透。Pinia 相比 Vuex 的改进：去掉 mutation 同步约束、天然代码分割与按需加载、完整的 TypeScript 推导、组合式与选项式两种写法、模块扁平化不再嵌套命名空间。实践要点：state 用组合式函数定义，异步动作放 action，getter 做派生；组件仍保留纯本地的 UI 状态（如弹窗开关），不是所有状态都要进 store。能说出「哪些状态该进 store」的判断标准（是否跨组件、是否需要持久化、是否服务端数据缓存）是加分项。',
 '组件通信,props,emit,单向数据流,provide,inject,defineExpose,事件总线,Pinia,Vuex,状态管理,action,getter,持久化,props钻透,devtools',
 'vue3', 'MANUAL', 'ENABLED'),

(2, 'Vite 为什么比 Webpack 快',
 '两个阶段分别回答。开发期：Vite 基于浏览器原生 ES 模块，启动时不打包，按需编译——浏览器请求某模块时 Vite 用 esbuild（Go 编写，比 JS 编写的编译器快一到两个数量级）即时转译该文件，冷启动时间与项目规模解耦；依赖预构建把 CommonJS 与 UMD 依赖批量转为 ESM 并做合并减少请求数，强缓存于 node_modules 内的 .vite 目录。Webpack 开发期要从入口递归打包全部模块才能启动，项目越大越慢。热更新：Vite 的 HMR 粒度在原生 ESM 上，编辑单文件只需精确失效该模块链，不必重新构建整包；加上 HTTP 缓存协商（304）与强缓存依赖，二次访问接近即时。生产构建：Vite 用 Rollup（输出更干净、tree shaking 更彻底），配 terser 或 esbuild 压缩。为什么生产不直接用原生 ESM：网络瀑布与请求数、兼容性、产物优化（tree shaking、懒加载、代码分割）仍需打包。加分点：说清分包策略 manualChunks 与预构建配置 optimizeDeps 的实际调优经验。',
 'Vite,Webpack,ESM,esbuild,按需编译,预构建,依赖优化,HMR,冷启动,Rollup,tree shaking,代码分割,manualChunks,optimizeDeps,304协商缓存',
 'engineering', 'MANUAL', 'ENABLED'),

(2, '环境变量管理与构建发布流程',
 '环境管理的核心原则：配置与代码分离，秘密永不进仓库。分层实践：代码里通过 import.meta.env（Vite）或 process.env（Webpack DefinePlugin）读取编译期注入的环境变量；.env.development 与 .env.production 存非敏感配置，.env.local 本地覆盖且被 git 忽略；真正敏感的密钥（支付、监控上传地址带 token 的）不应出现在前端产物里——前端环境变量本质是公开的，敏感操作必须走后端代理或网关注入。多环境（开发、测试、预发、生产）用模式区分：构建命令加 mode 参数，CI 按分支或标签选择模式与环境变量组。发布流程标准链路：代码合并触发流水线，静态检查（lint 与类型检查）→ 单测 → 构建产物（带 contenthash）→ 产物上传对象存储或镜像 → CDN 刷新或灰度发布 → 冒烟验证。回滚策略：保留历史产物目录，入口 HTML 指向固定版本路径，回滚即切指针。常见追问「前端如何做灰度」：按流量比例或用户标识分流到不同产物目录，或特性开关（feature flag）控制。加分点：说出你们项目里一次环境变量引发的故障与改进。',
 '环境变量,import.meta.env,DefinePlugin,.env.local,配置分离,多环境,模式,CI,流水线,lint,类型检查,contenthash,CDN,灰度发布,特性开关,回滚',
 'engineering', 'MANUAL', 'ENABLED'),

(2, '首屏加载慢的测量与优化',
 '先测量后优化。指标：FCP 首次内容绘制、LCP 最大内容绘制（核心阈值 2.5 秒内）、TTI 可交互时间、CLS 布局偏移。工具：Lighthouse 审计、Performance 面板看主线程与网络瀑布、Web Vitals 采集真实用户数据。定位后按资源与执行两条线优化。资源线：路由级与组件级代码分割（动态 import），首屏只加载关键 chunk；JS 压缩与 tree shaking；图片用现代格式与合适尺寸、懒加载、首屏关键图片 preload 与 fetchpriority 提权；字体子集化与 font-display swap 避免文字不可见；第三方脚本 defer 或按需加载。执行线：长任务切片（时间分片）、避免主线程大计算、关键 CSS 内联其余异步。网络线：HTTP2 多路复用、CDN 就近、资源预连接与预解析、开启压缩与缓存策略。服务端渲染或静态生成是把首屏 HTML 直出，配合流式渲染与岛屿架构（局部水合）进一步降低 TTI。回答时给出「测量发现 LCP 3.8 秒，主因是首屏大图与主 bundle 过大，做分割加图片优化后降到 1.9 秒」这类具体闭环，比罗列手段有说服力。',
 '首屏优化,FCP,LCP,TTI,CLS,Lighthouse,Performance面板,代码分割,动态import,tree shaking,图片懒加载,字体子集化,关键CSS,CDN,SSR,流式渲染,岛屿架构,预加载',
 'performance', 'MANUAL', 'ENABLED'),

(2, '长列表渲染卡顿的优化方案',
 '万条数据卡顿的根因：DOM 节点过多导致内存占用高、样式计算与布局成本随节点数线性增长、一次性渲染阻塞主线程。方案分层。虚拟滚动是主解：只渲染可视区域加缓冲区的几十条，滚动时按位移换算起始索引替换渲染，配绝对定位或 transform 占位保持滚动条高度；实现要点是固定行高与动态行高两种模式（动态行高需预估与测量缓存）、快速滚动白屏用缓冲区与骨架屏兜底；Vue 生态可用 vue-virtual-scroller 或自实现。数据与交互层：分页或无限滚动按需追加；输入驱动的重渲染用节流或输入防抖；行组件 memo 化（v-memo 或 props 恒定性）避免无关更新；列表项事件用事件委托减少监听器数量。骨架屏与占位高度防止滚动跳动。加分深度：说清虚拟列表在移动端惯性滚动时的帧预算（16 毫秒内完成换帧）、requestAnimationFrame 节流滚动计算、离屏 canvas 渲染超大规模数据的边界方案。回答给出量化对比（优化前滚动帧率 15 帧，虚拟化后稳定 60 帧）最可信。',
 '长列表,虚拟滚动,可视区域,缓冲区,动态行高,固定行高,分页,无限滚动,防抖,节流,v-memo,事件委托,骨架屏,帧率,requestAnimationFrame,DOM数量',
 'performance', 'MANUAL', 'ENABLED'),

(2, '打包体积分析与瘦身',
 '流程：先分析再优化再验证。分析工具：rollup-plugin-visualizer 或 webpack-bundle-analyzer 生成占比图，看 source-map-explorer 按文件归因；构建命令输出 gzip 后体积对比基线。常见大头与对策：整包引入组件库改为按需自动导入（unplugin-vue-components 与 unplugin-auto-import）；moment 换 dayjs、lodash 换按路径引入或 lodash-es 配 tree shaking；没用到的 polyfill 与 core-js 版本收敛；重复依赖用 resolutions 或别名去重（常见于工具库各自打包 axios）。代码分割：路由级动态 import、大而低频的组件（图表、富文本）懒加载、第三方分组 manualChunks 拆 vendor 利用缓存。图片与字体：压缩、WebP、字体子集。运行时优化与体积的权衡：预加载关键 chunk 防 waterfall。验证闭环：构建产物体积报表进 CI 卡阈值，体积回归即报警。回答模板：分析发现 echarts 与 moment 占 60%，按需引入加替换后主包从 1.8M 降到 600K，首屏 JS 从 1.2M 降到 380K，LCP 从 3.5 秒改善到 1.8 秒。有数字有手段有验证，就是高质量回答。',
 '打包体积,bundle分析,visualizer,按需引入,tree shaking,lodash-es,dayjs,manualChunks,代码分割,懒加载,重复依赖,polyfill,字体子集,WebP,体积基线,CI卡口',
 'performance', 'MANUAL', 'ENABLED'),

(2, 'XSS 原理、类型与防御体系',
 'XSS 是攻击者把恶意脚本注入页面，在受害者浏览器执行，可窃取 Cookie 与令牌、伪造请求、篡改页面。三类：存储型（恶意内容入库，如评论字段，所有浏览者中招，危害最大）；反射型（恶意脚本在 URL 参数里，服务端回显，需诱导点击）；DOM 型（纯前端把不可信数据写入 HTML，如 innerHTML 拼接 location.hash，服务端无感知）。防御分层：输出转义是根本——按上下文（HTML 体、属性、JS、URL）选择转义规则，前端框架默认转义插值天然防大部分 XSS，风险点在 v-html、dangerouslySetInnerHTML、innerHTML、href javascript 伪协议；输入校验做白名单长度与格式，但不能替代输出转义；Cookie 防窃取配 HttpOnly（JS 读不到）与 Secure、SameSite；CSP 内容安全策略（nonce 或白名单脚本源）作为纵深防御阻断内联脚本执行；富文本场景用白名单过滤库（如 DOMPurify）清洗标签与属性。加分点：说明存储型要「入库过滤加出库转义」双保险、CSP 上线前先用 Report-Only 观察误伤，以及提到 SameSite 对 CSRF 的连带防护边界。',
 'XSS,存储型,反射型,DOM型,输出转义,上下文转义,v-html,innerHTML,HttpOnly,SameSite,CSP,DOMPurify,白名单过滤,富文本,令牌窃取,javascript伪协议',
 'security', 'MANUAL', 'ENABLED'),

(2, 'CSRF 原理与防御',
 'CSRF 利用浏览器自动携带 Cookie 的机制：用户登录态下访问恶意页面，该页面对目标站点发请求（表单提交、图片地址、fetch），浏览器自动带上 Cookie，服务器误认为是用户本人操作。与 XSS 的本质区别：CSRF 冒用身份但不能读取响应数据，XSS 是脚本直接执行几乎无限制；CSRF 攻击者拿不到令牌，XSS 可以偷令牌。防御手段按有效性：SameSite Cookie（Lax 默认阻止跨站 POST 携带，现代浏览器第一道防线）；CSRF Token（服务端下发随机 token，请求须带回并校验，攻击者跨站读不到该 token）；校验 Origin 与 Referer 头（简单有效，但注意某些隐私设置下缺失需兜底策略）；关键操作二次确认（密码、验证码）。JWT 存 Header 的方案天然免疫 CSRF（攻击者无法自定义跨站请求头且读不到 token），但要防 XSS 偷 token，与存 Cookie 的取舍正好相反：Cookie 配 HttpOnly 防 XSS 难防 CSRF，Header 防.csrf 难防 XSS，需配合对应的另一侧防御。回答能点破这个对称权衡，就是满分信号。',
 'CSRF,SameSite,Lax,CSRF Token,Origin,Referer,跨站请求,登录态,Cookie自动携带,JWT,Header,二次确认,XSS对比,对称权衡,防护策略',
 'security', 'MANUAL', 'ENABLED'),

(2, '前端登录态存储的权衡',
 '三种主流方案对比。Cookie 存储：可配 HttpOnly（JS 不可读，防 XSS 窃取）、Secure（仅 HTTPS）、SameSite（防 CSRF）、过期与作用域管理由浏览器负责自动携带；缺点是容量小、跨域要配 CORS withCredentials、历史上有 CSRF 风险需 SameSite 缓解。localStorage 存 token：API 简单、容量较大、跨子域方便（同源即可）；致命点是 JS 可读，一旦 XSS 即泄露，且无法配 HttpOnly。内存存储（变量或 Pinia）：最抗窃取（刷新丢失），配静默刷新机制（刷新页面前先换新 token）是安全与体验兼顾的高阶方案。推荐架构：长期凭证用 HttpOnly Cookie（刷新令牌），短期访问令牌放内存，请求头携带；配合后端轮换与异常登录检测。单点登录场景用统一认证域加 Cookie 顶域共享或授权码模式。回答要点在于展示「威胁模型思维」：明确防什么（XSS 偷 token、CSRF 冒用、网络窃听）、每个存储位置的攻防面，再给团队场景下的选型结论；只说「我用 localStorage」而无分析是典型失分。',
 '登录态,Cookie,HttpOnly,Secure,SameSite,localStorage,内存存储,访问令牌,刷新令牌,静默刷新,令牌轮换,单点登录,威胁模型,XSS,CSRF,授权码',
 'security', 'MANUAL', 'ENABLED'),

(2, '可复用组件的设计方法',
 '组件设计的核心是「稳定契约、开放扩展」。设计步骤：先抽象职责边界——一个组件只做一件事，展示型组件管渲染不管数据，容器型组件管数据与编排；再定 API 契约：props 定义输入（必选可选、类型、默认值、校验），emit 定义输出事件（载荷结构明确），slot 定义内容扩展点（默认、具名、作用域插槽把内部状态交给外部渲染）。参考成熟组件库的 API 设计惯例：受控与非受控双模式（v-model 语法糖与 defaultValue 回退）、状态提升的边界、Provide 注入的层级配置（如 Form 给 FormItem 的校验上下文）。举例模板：封装一个通用搜索选择器，props 控制 数据源方法、是否可搜索、分页参数；emit 抛出选择与清除事件；具名插槽自定义选项渲染；把防抖搜索逻辑内置，暴露 loading 状态。质量保障：组件库按目录分层（基础组件、业务组件）、Storybook 隔离演示与视觉回归、单测覆盖交互分支、changesets 管理版本。避免过度设计：项目里两三处复用先抽组合函数，四处以上再沉淀组件。能讲清「什么时候不该抽组件」同样是设计能力的体现。',
 '组件设计,props,emit,slot,作用域插槽,受控非受控,v-model,展示型组件,容器组件,插槽扩展,防抖搜索,Storybook,视觉回归,组合函数,过度设计,API契约',
 'project_ux', 'MANUAL', 'ENABLED'),

(2, '前后端联调的问题与规范治理',
 '联调常见问题三类：契约不一致（字段名大小写、时间格式、空值表示、分页结构不同）、错误处理不一致（HTTP 状态码与业务码混用、错误信息无法定位）、环境不一致（本地、联调环境数据与配置差异导致「我这里好的」。治理方案：契约先行——接口文档在开发前用 OpenAPI 或 Apifox 定义并冻结，前端用 mock 数据并行开发，后端实现完对齐文档再联调；类型共享——通过代码生成（openapi-typescript）或 monorepo 共享类型包，让字段不匹配在编译期暴露；错误规范——统一响应结构（业务码、消息、数据、追踪号），前端拦截器统一弹出与埋点；联调环境——独立后端分支部署加前端代理配置切换，避免共用环境互相覆盖；变更流程——接口改动必须走文档评审加变更通知，禁止口头改契约。排查工具链：抓包（浏览器 Network、代理断点）定位问题在前端还是后端，日志加追踪号串联两端。回答给出真实例子：时间字段一个用秒一个用毫秒导致列表排序错乱，之后规范全部 ISO 字符串并沉淀到类型定义，这类细节最可信。',
 '联调,接口契约,OpenAPI,Apifox,mock,类型共享,代码生成,统一响应,业务码,错误处理,环境不一致,代理配置,变更管理,抓包,追踪号,时间格式',
 'project_ux', 'MANUAL', 'ENABLED'),

(2, '多机型适配方案',
 '适配问题的三个层面与对应方案。视口与缩放：移动端配 meta viewport，宽度适配用 rem 或 vw 方案（postcss-px-to-viewport 把设计稿像素转视口单位），根字号随屏幕宽度换算；弹性布局用 flex 与 grid 处理比例伸缩，栅格断点响应式（媒体查询或容器查询）处理平板与桌面。设计还原与容错：极端窄屏与长文案（英文单词不换行用 overflow-wrap、多行省略 line-clamp）、图片自适应（srcset 按像素密度选择、object-fit 裁切）、安全区适配（刘海屏 env safe-area-inset）。一致性验证：真机测试矩阵覆盖主流机型与系统版本、浏览器开发者工具设备模拟做初筛、云真机平台补全覆盖、视觉走查（设计师标注对比）加截图回归。1 物理像素边线用 transform scale 或 0.5px 处理。等比缩放的争议点值得主动提：整体等比（viewport 缩放）在大屏浪费空间，行业更倾向「流式布局加关键内容等比」的混合策略，信息密度随屏幕自适应。回答时点出你们项目的设计稿基准与断点定义，说明落地细节。',
 '适配,viewport,rem,vw,px-to-viewport,弹性布局,栅格,断点,媒体查询,容器查询,srcset,object-fit,安全区,line-clamp,真机测试,像素密度,1px边线',
 'project_ux', 'MANUAL', 'ENABLED'),

(2, '复杂表单联动与输入性能优化',
 '问题拆解：复杂表单的性能瓶颈通常在「每次输入触发全表单重渲染」与「联动计算昂贵」两点。优化策略分四层。渲染层：把表单拆成小粒度字段组件，配合组件 memo（v-memo 或 React useMemo）让未变化的字段不重渲染；输入频率与渲染频率解耦——输入防抖后再触发联动计算（150 到 300 毫秒），即时反馈（如字数统计）用非受控或本地状态处理。数据层：联动逻辑集中到状态机或配置驱动的联动描述（字段依赖图），而不是散落在模板里的一堆 watch；计算属性缓存派生值，避免每次渲染重算；深比较默认值用浅比较或结构共享。体验层：异步校验（如用户名查重）防抖加取消过期请求（标记最新请求标识）；提交前集中校验并滚动到第一个错误项；长表单分步保存草稿。极端场景：超长动态列表表单用虚拟滚动或分区渲染。回答建议给结构：字段数、联动规则数、优化前后的输入延迟对比（如输入卡顿 300 毫秒降到 30 毫秒内），以及最终选用的方案组合。能提到「把校验规则与联动配置声明式化，新表单开发成本减半」属于亮点。',
 '表单性能,联动,防抖,组件拆分,局部渲染,v-memo,计算属性,依赖图,配置驱动,异步校验,取消过期请求,分步表单,草稿保存,虚拟滚动,声明式校验',
 'project_ux', 'MANUAL', 'ENABLED');
